ALTER TABLE "pacientes" ADD COLUMN "telefone_normalizado" text GENERATED ALWAYS AS (case when (case when length(regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '')) in (12, 13) and regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '') like '55%' then substr(regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', ''), 3) else regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '') end) ~ '^[1-9][0-9]{9,10}$' then '+55' || (case when length(regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '')) in (12, 13) and regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '') like '55%' then substr(regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', ''), 3) else regexp_replace(regexp_replace(coalesce(telefone, ''), '\D', '', 'g'), '^00', '') end) end) STORED;--> statement-breakpoint
CREATE INDEX "pacientes_tenant_telefone_idx" ON "pacientes" USING btree ("tenant_id","telefone_normalizado");